OPENING_FOLDERS.forEach(f => {
  f.lines = OPENINGS_DATA.filter(o => o.folderId === f.id);
});

function getAllOpeningsList() {
  return OPENINGS_DATA;
}

if (typeof window !== 'undefined') {
  window.OPENING_FOLDERS = OPENING_FOLDERS;
  window.OPENINGS_DATA = OPENINGS_DATA;
  window.getAllOpeningsList = getAllOpeningsList;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { OPENING_FOLDERS, OPENINGS_DATA, getAllOpeningsList };
}
